import type { AyahRef, QuranIndex, SurahData } from './types';
import { getSurah as loadSurah } from './surah-map';

// Bundled Quran data (Tanzil Hafs text, generated by scripts/build-quran-data.mjs).
// Per-surah JSON is loaded on demand via the generated async loader, so the
// web build code-splits each surah into its own chunk.

const index = require('../../assets/data/quran/index.json') as QuranIndex;

export function getIndex(): QuranIndex {
  return index;
}

/** Loads one surah on demand. Returns undefined for invalid surah numbers. */
export async function getSurah(number: number): Promise<SurahData | undefined> {
  return loadSurah(number);
}

/** 1-based global ayah position across the Quran (1..6236). */
export function globalAyahNumber(ref: AyahRef): number {
  if (ref.surah < 1 || ref.surah > 114) return 0;
  return (index.surahPrefix[ref.surah - 1] ?? 0) + ref.ayah;
}

/** Global ayah number of the first ayah of each juz (1..30). O(1). */
export function juzStartGlobal(juz: number): number {
  return juz >= 1 && juz <= 30 ? index.juzStarts[juz - 1] : 0;
}
